def to_stream(iter) do
  Stream.resource(
    fn -> iter end,
    fn iter ->
      case Iterable.next(iter.iterable) do
        {:ok, element, iterable} -> {[element], %{iter | iterable: iterable}}
        :done -> {:halt, iter}
      end
    end,
    fn _ -> :ok end
  )
end

