def module_scope(%__MODULE__{} = analysis, %Range{} = range) do
  enclosing_scopes = analysis |> scopes_at(range.start) |> enclosing_scopes(range)
  first_scope = List.first(enclosing_scopes)

  Enum.reduce_while(enclosing_scopes, first_scope, fn
    %Scope{module: same} = current, %Scope{module: same} -> {:cont, current}
    _, current -> {:halt, current}
  end)
end

