    not stop_visited? -> {:cont, {first_stop, stop_visited?}}
    prev_stop_visited? -> {:cont, {stop, stop_visited?}}
    not prev_stop_visited? -> {:cont, {first_stop, stop}, {stop, stop_visited?}}
  end
end

