def parse(media) do
  withl(
    conn: [type, port, proto, fmt] <- String.split(media, " ", parts: 4),
    port: {port, port_count} when port in 0..65535 <- Integer.parse(port),
    port_count: port_count when port_count > 0 <- parse_port_count(port_count),
    fmt: {:ok, fmt} <- parse_fmt(fmt, proto)
  ) do
    media = %__MODULE__{
      type: parse_type(type),
      port: port,
      port_count: port_count,
      protocol: proto,
      fmt: fmt
    }

    {:ok, media}
  else
    [conn: _error] -> {:error, :invalid_media_spec}
    [port: _error] -> {:error, :invalid_port_number}
    [port_count: _error] -> {:error, :invalid_port_count}
    [fmt: error] -> error
  end
end

