def create_plc_packets(gap_start_timestamp, gap_duration) do
  if rem(gap_duration, @shortest_frame_duration) != 0 do
    Membrane.Logger.warning(
      "Theoretically impossible gap in Opus stream of #{Membrane.Time.as_milliseconds(gap_duration, :exact) |> Ratio.to_float()}ms"
    )
  end

  packets_to_generate = div(gap_duration + Membrane.Time.millisecond(), @shortest_frame_duration)

  Range.to_list(0..(packets_to_generate - 1))
  |> Enum.map(
    &%{
      payload: @plc_packet_for_2_5ms_gap,
      pts: gap_start_timestamp + &1 * @shortest_frame_duration,
      metadata: %{duration: @shortest_frame_duration}
    }
  )
end

def rest_of_packet(data, expected_packet_size) do
  case data do
    <<raw_packet::binary-size(^expected_packet_size), rest::binary>> -> {:ok, raw_packet, rest}
    _otherwise -> {:error, :cont}
  end
end

def get_processor(delimitation, self_delimiting?) do
  cond do
    self_delimiting? && delimitation == :undelimit -> {__MODULE__.Undelimiter, false}
    !self_delimiting? && delimitation == :delimit -> {__MODULE__.Delimiter, true}
    true -> {__MODULE__.Keeper, self_delimiting?}
  end
end

def calculate_padding_info(padding_flag, data, current_padding \\ 0, byte_offset \\ 0)
def calculate_padding_info(0, _data, _current_padding, _byte_offset) do
  {0, 0}
end
def calculate_padding_info(1, <<padding::size(8), rest::binary>>, current_padding, byte_offset)
    when padding == 255 do
  calculate_padding_info(1, rest, current_padding + 254, byte_offset + 1)
end
def calculate_padding_info(
      1,
      <<padding::size(8), _rest::binary>>,
      current_padding,
      byte_offset
    ) do
  {current_padding + padding, byte_offset + 1}
end
def calculate_padding_info(1, _data, _current_padding, _byte_offset) do
  :error
end

def code_one_lengths(<<_toc::binary-size(1), rest::binary>>, true) do
  case calculate_frame_length(rest, 0) do
    {length, length_bytes} -> {:ok, 1 + length_bytes, [length, length], 0}
    :error -> {:error, :cont}
  end
end
def code_one_lengths(<<_toc::binary-size(1), rest::binary>>, false) do
  length = div(byte_size(rest), 2)
  {:ok, 1, [length, length], 0}
end

